/* Generated by port_site.py from the approved mockup. Behaviour for the channels section; timers, listeners and observers go through ctx. */
export function init(ctx) {
  var reduce = ctx.reduce,
    root = document.documentElement;

  /* section 1: every few seconds one channel lights up, says what came in, and a message travels into the HAIP hub (Motion) */
  (function () {
    var orbit = document.querySelector(".orbit"),
      Mo = ctx.Motion,
      hub = orbit.querySelector(".hub"),
      seen = false,
      timer = null,
      k = 0;
    var WHO = {
      wa: "Rohan · WhatsApp",
      ig: "@ananya.travels · Instagram",
      ad: "Arjun · from your Meta ad",
      web: "Kavya · website enquiry",
      ota: "Booking from an OTA",
      ta: "Yatra Holidays · agent",
      walk: "Walk-in at the front desk",
      ref: "Dev · referred by a guest",
      call: "Meera · missed call",
    };
    var order = ["wa", "call", "ig", "web", "ad", "ota", "ref", "ta", "walk"];
    function send() {
      var key = order[k % order.length];
      k++;
      var ch = orbit.querySelector('.chan[data-key="' + key + '"]');
      if (!ch) return;
      var o = orbit.getBoundingClientRect(),
        r = ch.getBoundingClientRect(),
        x = r.left + r.width / 2 - o.left,
        y = r.top + r.height / 2 - o.top,
        cx = o.width / 2,
        cy = o.height / 2;
      ch.classList.add("on");
      var below = y < o.height * 0.3,
        pop = document.createElement("span");
      pop.className = "pop";
      pop.textContent = WHO[key];
      pop.style.left = x + "px";
      pop.style.top =
        (below ? y + r.height / 2 - 6 : y - r.height / 2 + 6) + "px";
      orbit.appendChild(pop);
      var t0 = below ? "translate(-50%,10%)" : "translate(-50%,-110%)",
        t1 = below ? "translate(-50%,40%)" : "translate(-50%,-140%)";
      pop.style.transform = t1;
      Mo.animate(
        pop,
        { opacity: [0, 1], transform: [t0, t1] },
        { duration: 0.3, easing: [0.22, 1, 0.36, 1] },
      );
      var dot = document.createElement("i");
      dot.className = "travel";
      orbit.appendChild(dot);
      var svg = document.getElementById("beam"),
        ln = document.createElementNS("http://www.w3.org/2000/svg", "line"),
        len = Math.hypot(cx - x, cy - y);
      svg.setAttribute("viewBox", "0 0 " + o.width + " " + o.height);
      ln.setAttribute("x1", x);
      ln.setAttribute("y1", y);
      ln.setAttribute("x2", cx);
      ln.setAttribute("y2", cy);
      var g = svg.querySelector("#beamg");
      g.setAttribute("x1", x);
      g.setAttribute("y1", y);
      g.setAttribute("x2", cx);
      g.setAttribute("y2", cy);
      ln.style.strokeDasharray = len;
      ln.style.strokeDashoffset = len;
      svg.appendChild(ln);
      ctx.setTimeout(function () {
        Mo.animate(
          ln,
          { strokeDashoffset: [len, 0] },
          { duration: 0.85, easing: [0.65, 0, 0.35, 1] },
        );
        Mo.animate(
          dot,
          {
            transform: [
              "translate(" + x + "px," + y + "px) scale(.6)",
              "translate(" + cx + "px," + cy + "px) scale(1)",
            ],
            opacity: [0, 1],
          },
          { duration: 0.85, easing: [0.65, 0, 0.35, 1] },
        ).then(function () {
          dot.remove();
          ch.classList.remove("on");
          Mo.animate(ln, { opacity: [1, 0] }, { duration: 0.5 }).then(
            function () {
              ln.remove();
            },
          );
          var wv = document.createElement("i");
          wv.className = "wave";
          orbit.appendChild(wv);
          Mo.animate(
            wv,
            {
              transform: [
                "translate(-50%,-50%) scale(1)",
                "translate(-50%,-50%) scale(2.3)",
              ],
              opacity: [0.6, 0],
            },
            { duration: 1.3, easing: [0.22, 1, 0.36, 1] },
          ).then(function () {
            wv.remove();
          });
          Mo.animate(
            hub,
            {
              transform: [
                "translate(-50%,-50%) scale(1)",
                "translate(-50%,-50%) scale(1.07)",
                "translate(-50%,-50%) scale(1)",
              ],
            },
            { duration: 0.45, easing: [0.22, 1, 0.36, 1] },
          );
          Mo.animate(
            pop,
            { opacity: [1, 0] },
            { duration: 0.4, delay: 0.5 },
          ).then(function () {
            pop.remove();
          });
        });
      }, 350);
    }
    function tick() {
      ctx.clearTimeout(timer);
      if (!Mo || reduce || document.hidden || !seen) {
        timer = null;
        return;
      }
      timer = ctx.setTimeout(function () {
        send();
        tick();
      }, 2000);
    }
    if (!reduce && matchMedia("(hover:hover) and (pointer:fine)").matches) {
      var sec1 = document.getElementById("channels");
      ctx.on(sec1, "pointermove", function (e) {
        var r = orbit.getBoundingClientRect();
        orbit.style.setProperty(
          "--px",
          Math.max(
            -1,
            Math.min(1, (e.clientX - r.left - r.width / 2) / (r.width / 2)),
          ).toFixed(3),
        );
        orbit.style.setProperty(
          "--py",
          Math.max(
            -1,
            Math.min(1, (e.clientY - r.top - r.height / 2) / (r.height / 2)),
          ).toFixed(3),
        );
      });
      ctx.on(sec1, "pointerleave", function () {
        orbit.style.setProperty("--px", 0);
        orbit.style.setProperty("--py", 0);
      });
    }
    if ("IntersectionObserver" in window)
      ctx
        .io(
          function (es) {
            seen = es[0].isIntersecting;
            tick();
          },
          { threshold: 0.3 },
        )
        .observe(orbit);
    ctx.on(document, "visibilitychange", tick);
  })();
}
